import unittest
from candidate import vowels_count

class TestVowelsCount(unittest.TestCase):
    def test_normal_case_lowercase(self):
        self.assertEqual(vowels_count("hello"), 2)

    def test_normal_case_uppercase(self):
        self.assertEqual(vowels_count("HELLO"), 2)

    def test_normal_case_mixed(self):
        self.assertEqual(vowels_count("HElLo"), 2)

    def test_normal_case_with_y_at_end(self):
        self.assertEqual(vowels_count("rhythm"), 1)

    def test_normal_case_with_y_not_at_end(self):
        self.assertEqual(vowels_count("myth"), 0)

    def test_empty_string(self):
        self.assertEqual(vowels_count(""), 0)

    def test_single_character_non_vowel(self):
        self.assertEqual(vowels_count("b"), 0)

    def test_single_character_vowel(self):
        self.assertEqual(vowels_count("a"), 1)

    def test_single_character_y_at_end(self):
        self.assertEqual(vowels_count("y"), 1)

    def test_string_with_only_y_at_end(self):
        self.assertEqual(vowels_count("yy"), 1)

    def test_string_with_y_not_at_end(self):
        self.assertEqual(vowels_count("ayy"), 1)

    def test_string_with_y_in_middle(self):
        self.assertEqual(vowels_count("ayy"), 1)

    def test_case_insensitive_vowels(self):
        self.assertEqual(vowels_count("AEIOUaeiou"), 10)

    def test_string_with_all_vowels(self):
        self.assertEqual(vowels_count("aeiou"), 5)

    def test_string_with_all_consonants(self):
        self.assertEqual(vowels_count("bcdfg"), 0)

    def test_string_with_y_as_vowel(self):
        self.assertEqual(vowels_count("sky"), 1)

    def test_string_with_y_as_non_vowel(self):
        self.assertEqual(vowels_count("myth"), 0)

    def test_none_input(self):
        with self.assertRaises(TypeError):
            vowels_count(None)

    def test_non_string_input(self):
        with self.assertRaises(TypeError):
            vowels_count(123)

    def test_string_with_numbers(self):
        self.assertEqual(vowels_count("a1e2i3o4u5"), 5)

    def test_string_with_special_characters(self):
        self.assertEqual(vowels_count("h3ll0 w0rld!"), 2)

    def test_boundary_case_single_vowel_y(self):
        self.assertEqual(vowels_count("y"), 1)

    def test_boundary_case_multiple_y_at_end(self):
        self.assertEqual(vowels_count("xyz"), 2)

    def test_boundary_case_multiple_y_not_at_end(self):
        self.assertEqual(vowels_count("ayby"), 1)

    def test_case_insensitive_with_y(self):
        self.assertEqual(vowels_count("Rhythm"), 1)
